internal object LauncherTranslationChunk6 {
    val entries = mapOf(
        "Original game installed" to arrayOf("Na-install ang orihinal na laro", "\uC6D0\uBCF8 \uAC8C\uC784 \uC124\uCE58\uB428", "\u5143\u306E\u30B2\u30FC\u30E0\u304C\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3055\u308C\u307E\u3057\u305F", "\u5DF2\u5B89\u88C5\u539F\u59CB\u6E38\u620F", "Juego original instalado", "Tr\u00F2 ch\u01A1i g\u1ED1c \u0111\u00E3 \u0111\u01B0\u1EE3c c\u00E0i \u0111\u1EB7t", "Game asli terinstal", "Jogo original instalado", "تم تثبيت اللعبة الأصلية"),
        "Outdated add-on" to arrayOf("Lipas na add-on", "\uAD6C\uC2DD \uCD94\uAC00 \uAE30\uB2A5", "\u53E4\u3044\u30A2\u30C9\u30AA\u30F3", "\u63D2\u4EF6\u5DF2\u8FC7\u65F6", "Complemento desactualizado", "Ph\u1EA7n b\u1ED5 sung \u0111\u00E3 l\u1ED7i th\u1EDDi", "Tambahan usang", "Complemento desatualizado", "الوظيفة الإضافية التي عفا عليها الزمن"),
        "Package couldn't be verified" to arrayOf("Hindi ma-verify ang package", "\uD328\uD0A4\uC9C0\uB97C \uD655\uC778\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u78BA\u8A8D\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F", "\u65E0\u6CD5\u9A8C\u8BC1\u7A0B\u5E8F\u5305", "No se pudo verificar el paquete", "G\u00F3i kh\u00F4ng th\u1EC3 \u0111\u01B0\u1EE3c x\u00E1c minh", "Paket tidak bisa diverifikasi", "N\u00E3o foi poss\u00EDvel verificar o pacote", "لا يمكن التحقق من الحزمة"),
        "Package verification completed successfully" to arrayOf("Matagumpay na nakumpleto ang pag-verify ng package", "\uD328\uD0A4\uC9C0 \uD655\uC778 \uC644\uB8CC", "\u30D1\u30C3\u30B1\u30FC\u30B8\u306E\u78BA\u8A8D\u304C\u6B63\u5E38\u306B\u5B8C\u4E86\u3057\u307E\u3057\u305F", "\u7A0B\u5E8F\u5305\u9A8C\u8BC1\u6210\u529F\u5B8C\u6210", "Verificaci\u00F3n del paquete completada con \u00E9xito", "X\u00E1c minh g\u00F3i ho\u00E0n t\u1EA5t th\u00E0nh c\u00F4ng", "Verifikasi paket berhasil diselesaikan", "Verifica\u00E7\u00E3o do pacote conclu\u00EDda com sucesso", "تم التحقق من الحزمة بنجاح"),
        "Package: {0} \u00B7 {1} bytes" to arrayOf("Package: {0} \u00B7 {1} bytes", "\uD328\uD0A4\uC9C0: {0} \u00B7 {1} \uBC14\uC774\uD2B8", "\u30D1\u30C3\u30B1\u30FC\u30B8: {0} \u00B7 {1} \u30D0\u30A4\u30C8", "\u7A0B\u5E8F\u5305\uFF1A{0} \u00B7 {1} \u5B57\u8282", "Paquete: {0} \u00B7 {1} bytes", "G\u00F3i: {0} \u00B7 {1} byte", "Paket: {0} \u00B7 {1} bytes", "Pacote: {0} \u00B7 {1} bytes", "الحزمة: {0} · {1} بايت"),
        "Patch verified and ready" to arrayOf("Na-verify at handa na ang patch", "\uD328\uCE58 \uD655\uC778 \uC644\uB8CC \uBC0F \uC900\uBE44\uB428", "\u30D1\u30C3\u30C1\u304C\u78BA\u8A8D\u3055\u308C\u3001\u6E96\u5099\u5B8C\u4E86", "\u8865\u4E01\u5DF2\u9A8C\u8BC1\u5E76\u51C6\u5907\u5C31\u7EEA", "Parche verificado y listo", "B\u1EA3n v\u00E1 \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh v\u00E0 s\u1EB5n s\u00E0ng", "Patch diverifikasi dan siap", "Patch verificado e pronto", "تم التحقق من التصحيح وجاهز"),
        "Paused before this download began" to arrayOf("Huminto bago magsimula ang pag-download na ito", "\uC774 \uB2E4\uC6B4\uB85C\uB4DC\uAC00 \uC2DC\uC791\uB418\uAE30 \uC804\uC5D0 \uC77C\uC2DC \uC911\uC9C0\uB428", "\u3053\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u958B\u59CB\u3059\u308B\u524D\u306B\u4E00\u6642\u505C\u6B62\u3057\u307E\u3057\u305F", "\u5728\u6B64\u4E0B\u8F7D\u5F00\u59CB\u4E4B\u524D\u5DF2\u6682\u505C", "Pausado antes de que comenzara esta descarga", "T\u1EA1m d\u1EEBng tr\u01B0\u1EDBc khi b\u1EAFt \u0111\u1EA7u t\u1EA3i xu\u1ED1ng n\u00E0y", "Dijeda sebelum unduhan ini dimulai", "Pausado antes do in\u00EDcio deste download", "تم الإيقاف مؤقتًا قبل بدء هذا التنزيل"),
        "Paused safely; tap Update whenever you're ready" to arrayOf("Maingat na huminto; i-tap ang Update kapag handa ka na", "\uC548\uC804\uD558\uAC8C \uC77C\uC2DC \uC911\uC9C0\uB428; \uC900\uBE44\uB418\uBA74 \uC5C5\uB370\uC774\uD2B8\uB97C \uB204\uB974\uC138\uC694", "\u5B89\u5168\u306B\u4E00\u6642\u505C\u6B62\u3057\u307E\u3057\u305F\u3002\u6E96\u5099\u304C\u3067\u304D\u305F\u3089[\u66F4\u65B0]\u3092\u30BF\u30C3\u30D7\u3057\u3066\u304F\u3060\u3055\u3044", "\u5DF2\u5B89\u5168\u6682\u505C\uFF1B\u51C6\u5907\u597D\u65F6\u70B9\u51FB\u66F4\u65B0", "Pausado de manera segura; toca Actualizar cuando est\u00E9s listo", "T\u1EA1m d\u1EEBng an to\u00E0n; nh\u1EA5n C\u1EADp nh\u1EADt khi b\u1EA1n s\u1EB5n s\u00E0ng", "Dijeda dengan aman; ketuk Perbarui kapan pun Anda siap", "Pausado com seguran\u00E7a; toque em Atualizar quando estiver pronto", "توقف بأمان؛ انقر فوق تحديث عندما تكون مستعدًا"),
        "Please start the update again." to arrayOf("Mangyaring simulan muli ang update.", "\uC5C5\uB370\uC774\uD2B8\uB97C \uB2E4\uC2DC \uC2DC\uC791\uD558\uC138\uC694.", "\u66F4\u65B0\u3092\u3082\u3046\u4E00\u5EA6\u958B\u59CB\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u8BF7\u518D\u6B21\u5F00\u59CB\u66F4\u65B0\u3002", "Por favor, inicia la actualizaci\u00F3n de nuevo.", "Vui l\u00F2ng b\u1EAFt \u0111\u1EA7u c\u1EADp nh\u1EADt l\u1EA1i.", "Silakan mulai pembaruan lagi.", "Por favor, inicie a atualiza\u00E7\u00E3o novamente.", "يرجى بدء التحديث مرة أخرى."),
        "Prepared package passed verification" to arrayOf("Ang inihandang pakete ay pumasa sa beripikasyon", "\uC900\uBE44\uB41C \uD328\uD0A4\uC9C0\uAC00 \uAC80\uC99D\uC744 \uD1B5\uACFC\uD588\uC2B5\uB2C8\uB2E4", "\u6E96\u5099\u3055\u308C\u305F\u30D1\u30C3\u30B1\u30FC\u30B8\u306F\u691C\u8A3C\u306B\u5408\u683C\u3057\u307E\u3057\u305F", "\u5DF2\u51C6\u5907\u7684\u5305\u901A\u8FC7\u9A8C\u8BC1", "Paquete preparado pas\u00F3 la verificaci\u00F3n", "G\u00F3i chu\u1EA9n b\u1ECB \u0111\u00E3 v\u01B0\u1EE3t qua x\u00E1c minh", "Paket yang disiapkan telah lolos verifikasi", "Pacote preparado passou na verifica\u00E7\u00E3o", "تم التحقق من الحزمة المعدة"),
        "Preparing Android installer" to arrayOf("Ipinaghahanda ang installer ng Android", "Android \uC124\uCE58 \uD504\uB85C\uADF8\uB7A8\uC744 \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4", "Android \u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059", "\u6B63\u5728\u51C6\u5907 Android \u5B89\u88C5\u7A0B\u5E8F", "Preparando el instalador de Android", "\u0110ang chu\u1EA9n b\u1ECB tr\u00ECnh c\u00E0i \u0111\u1EB7t Android", "Menyiapkan installer Android", "Preparando instalador Android", "تحضير مثبت الأندرويد"),
        "Preparing Android's installation screen. You can keep using the launcher while it opens." to arrayOf("Ipinaghahanda ang screen ng pag-install ng Android. Maaari mo pa ring gamitin ang launcher habang ito ay nagbubukas.", "Android \uC124\uCE58 \uD654\uBA74\uC744 \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4. \uC5F4\uB9AC\uB294 \uB3D9\uC548 \uB7F0\uCC98\uB97C \uACC4\uC18D \uC0AC\uC6A9\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.", "Android \u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u753B\u9762\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059\u3002\u958B\u3044\u3066\u3044\u308B\u9593\u3082\u30E9\u30F3\u30C1\u30E3\u30FC\u3092\u4F7F\u7528\u3067\u304D\u307E\u3059\u3002", "\u6B63\u5728\u51C6\u5907 Android \u7684\u5B89\u88C5\u754C\u9762\u3002\u6253\u5F00\u671F\u95F4\u60A8\u53EF\u4EE5\u7EE7\u7EED\u4F7F\u7528\u542F\u52A8\u5668\u3002", "Preparando la pantalla de instalaci\u00F3n de Android. Puedes seguir usando el lanzador mientras se abre.", "\u0110ang chu\u1EA9n b\u1ECB m\u00E0n h\u00ECnh c\u00E0i \u0111\u1EB7t c\u1EE7a Android. B\u1EA1n c\u00F3 th\u1EC3 ti\u1EBFp t\u1EE5c s\u1EED d\u1EE5ng tr\u00ECnh kh\u1EDFi ch\u1EA1y trong khi n\u00F3 m\u1EDF.", "Menyiapkan layar instalasi Android. Anda dapat terus menggunakan peluncur saat layar terbuka.", "Preparando a tela de instala\u00E7\u00E3o do Android. Voc\u00EA pode continuar usando o launcher enquanto ela abre.", "تحضير شاشة تثبيت أندرويد. يمكنك الاستمرار في استخدام المشغل أثناء فتحه."),
        "Preparing add-on controls, compatibility, and launch status\u2026" to arrayOf("Ipinaghahanda ang mga kontrol ng add-on, pagiging tugma, at katayuan ng paglulunsad\u2026", "\uC560\uB4DC\uC628 \uCEE8\uD2B8\uB864, \uD638\uD658\uC131 \uBC0F \uC2E4\uD589 \uC0C1\uD0DC\uB97C \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4\u2026", "\u30A2\u30C9\u30AA\u30F3\u306E\u30B3\u30F3\u30C8\u30ED\u30FC\u30EB\u3001\u4E92\u63DB\u6027\u3001\u8D77\u52D5\u72B6\u6CC1\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059\u2026", "\u6B63\u5728\u51C6\u5907\u9644\u52A0\u63A7\u4EF6\u3001\u517C\u5BB9\u6027\u548C\u542F\u52A8\u72B6\u6001\u2026", "Preparando controles adicionales, compatibilidad y estado de lanzamiento\u2026", "\u0110ang chu\u1EA9n b\u1ECB c\u00E1c \u0111i\u1EC1u khi\u1EC3n b\u1ED5 sung, kh\u1EA3 n\u0103ng t\u01B0\u01A1ng th\u00EDch v\u00E0 tr\u1EA1ng th\u00E1i kh\u1EDFi ch\u1EA1y\u2026", "Menyiapkan kontrol add-on, kompatibilitas, dan status peluncuran\u2026", "Preparando controles de add-on, compatibilidade e status de inicializa\u00E7\u00E3o\u2026", "جارٍ تحضير عناصر التحكم الإضافية والتوافق وحالة التشغيل..."),
        "Preparing device access details\u2026" to arrayOf("Ipinaghahanda ang mga detalye ng access ng device\u2026", "\uC7A5\uCE58 \uC811\uADFC \uC138\uBD80 \uC815\uBCF4\uB97C \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4\u2026", "\u30C7\u30D0\u30A4\u30B9\u30A2\u30AF\u30BB\u30B9\u306E\u8A73\u7D30\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059\u2026", "\u6B63\u5728\u51C6\u5907\u8BBE\u5907\u8BBF\u95EE\u8BE6\u60C5\u2026", "Preparando detalles de acceso al dispositivo\u2026", "\u0110ang chu\u1EA9n b\u1ECB chi ti\u1EBFt truy c\u1EADp thi\u1EBFt b\u1ECB\u2026", "Menyiapkan detail akses perangkat\u2026", "Preparando detalhes de acesso ao dispositivo\u2026", "جارٍ تحضير تفاصيل الوصول إلى الجهاز…"),
        "Preparing download" to arrayOf("Ipinaghahanda ang pag-download", "\uB2E4\uC6B4\uB85C\uB4DC\uB97C \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4", "\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059", "\u6B63\u5728\u51C6\u5907\u4E0B\u8F7D", "Preparando descarga", "\u0110ang chu\u1EA9n b\u1ECB t\u1EA3i xu\u1ED1ng", "Menyiapkan unduhan", "Preparando download", "جارٍ التحضير للتحميل"),
        "Preparing install details\u2026" to arrayOf("Ipinaghahanda ang mga detalye ng pag-install\u2026", "\uC124\uCE58 \uC138\uBD80 \uC815\uBCF4\uB97C \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4\u2026", "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306E\u8A73\u7D30\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059\u2026", "\u6B63\u5728\u51C6\u5907\u5B89\u88C5\u8BE6\u60C5\u2026", "Preparando detalles de instalaci\u00F3n\u2026", "\u0110ang chu\u1EA9n b\u1ECB chi ti\u1EBFt c\u00E0i \u0111\u1EB7t\u2026", "Menyiapkan detail instalasi\u2026", "Preparando detalhes de instala\u00E7\u00E3o\u2026", "جارٍ تحضير تفاصيل التثبيت…"),
        "Preparing release history\u2026" to arrayOf("Ipinaghahanda ang kasaysayan ng release\u2026", "\uB9B4\uB9AC\uC2A4 \uAE30\uB85D\uC744 \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4\u2026", "\u30EA\u30EA\u30FC\u30B9\u5C65\u6B74\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059\u2026", "\u6B63\u5728\u51C6\u5907\u53D1\u5E03\u5386\u53F2\u2026", "Preparando historial de versiones\u2026", "\u0110ang chu\u1EA9n b\u1ECB l\u1ECBch s\u1EED ph\u00E1t h\u00E0nh\u2026", "Menyiapkan riwayat rilis\u2026", "Preparando hist\u00F3rico de vers\u00F5es\u2026", "جارٍ تحضير سجل الإصدارات…"),
        "Preparing secure download" to arrayOf("Ipinaghahanda ang secure na pag-download", "\uC548\uC804\uD55C \uB2E4\uC6B4\uB85C\uB4DC\uB97C \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4", "\u5B89\u5168\u306A\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059", "\u6B63\u5728\u51C6\u5907\u5B89\u5168\u4E0B\u8F7D", "Preparando descarga segura", "\u0110ang chu\u1EA9n b\u1ECB t\u1EA3i xu\u1ED1ng an to\u00E0n", "Menyiapkan unduhan aman", "Preparando download seguro", "جارٍ التحضير للتنزيل الآمن"),
        "Preparing signed download" to arrayOf("Ipinaghahanda ang pinirmahang pag-download", "\uC11C\uBA85\uB41C \uB2E4\uC6B4\uB85C\uB4DC\uB97C \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4", "\u7F72\u540D\u4ED8\u304D\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059", "\u6B63\u5728\u51C6\u5907\u7B7E\u540D\u4E0B\u8F7D", "Preparando descarga firmada", "\u0110ang chu\u1EA9n b\u1ECB t\u1EA3i xu\u1ED1ng \u0111\u00E3 k\u00FD", "Menyiapkan unduhan yang ditandatangani", "Preparando download assinado", "جارٍ تحضير التنزيل الموقع"),
        "Preparing the add-on catalog\u2026" to arrayOf("Ipinaghahanda ang katalogo ng add-on\u2026", "\uC560\uB4DC\uC628 \uCE74\uD0C8\uB85C\uADF8\uB97C \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4\u2026", "\u30A2\u30C9\u30AA\u30F3\u30AB\u30BF\u30ED\u30B0\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059\u2026", "\u6B63\u5728\u51C6\u5907\u9644\u52A0\u7EC4\u4EF6\u76EE\u5F55\u2026", "Preparando el cat\u00E1logo de complementos\u2026", "\u0110ang chu\u1EA9n b\u1ECB danh m\u1EE5c add-on\u2026", "Menyiapkan katalog add-on\u2026", "Preparando o cat\u00E1logo de add-ons\u2026", "جارٍ تحضير كتالوج الإضافات…"),
        "Preparing update" to arrayOf("Ipinaghahanda ang pag-update", "\uC5C5\uB370\uC774\uD2B8\uB97C \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4", "\u66F4\u65B0\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059", "\u6B63\u5728\u51C6\u5907\u66F4\u65B0", "Preparando actualizaci\u00F3n", "\u0110ang chu\u1EA9n b\u1ECB c\u1EADp nh\u1EADt", "Menyiapkan pembaruan", "Preparando atualiza\u00E7\u00E3o", "جارٍ إعداد التحديث"),
        "Preparing update details\u2026" to arrayOf("Ipinaghahanda ang mga detalye ng pag-update\u2026", "\uC5C5\uB370\uC774\uD2B8 \uC138\uBD80 \uC815\uBCF4\uB97C \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4\u2026", "\u66F4\u65B0\u306E\u8A73\u7D30\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059\u2026", "\u6B63\u5728\u51C6\u5907\u66F4\u65B0\u8BE6\u60C5\u2026", "Preparando detalles de actualizaci\u00F3n\u2026", "\u0110ang chu\u1EA9n b\u1ECB chi ti\u1EBFt c\u1EADp nh\u1EADt\u2026", "Menyiapkan detail pembaruan\u2026", "Preparando detalhes da atualiza\u00E7\u00E3o\u2026", "جارٍ تحضير تفاصيل التحديث…"),
        "Preparing verified update" to arrayOf("Ipinaghahanda ang beripikadong pag-update", "\uAC80\uC99D\uB41C \uC5C5\uB370\uC774\uD2B8\uB97C \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4", "\u691C\u8A3C\u6E08\u307F\u306E\u66F4\u65B0\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059", "\u6B63\u5728\u51C6\u5907\u5DF2\u9A8C\u8BC1\u66F4\u65B0", "Preparando actualizaci\u00F3n verificada", "\u0110ang chu\u1EA9n b\u1ECB c\u1EADp nh\u1EADt \u0111\u00E3 \u0111\u01B0\u1EE3c x\u00E1c minh", "Menyiapkan pembaruan yang terverifikasi", "Preparando atualiza\u00E7\u00E3o verificada", "إعداد التحديث الذي تم التحقق منه"),
        "Preparing {0} update" to arrayOf("Ipinaghahanda ang {0} na pag-update", "{0} \uC5C5\uB370\uC774\uD2B8\uB97C \uC900\uBE44 \uC911\uC785\uB2C8\uB2E4", "{0} \u66F4\u65B0\u3092\u6E96\u5099\u3057\u3066\u3044\u307E\u3059", "\u6B63\u5728\u51C6\u5907 {0} \u66F4\u65B0", "Preparando actualizaci\u00F3n de {0}", "\u0110ang chu\u1EA9n b\u1ECB c\u1EADp nh\u1EADt {0}", "Menyiapkan pembaruan {0}", "Preparando atualiza\u00E7\u00E3o {0}", "جارٍ إعداد تحديث {0}."),
        "Preserving the untouched game and creating its exact-package compatibility shell." to arrayOf("Pinapangalagaan ang hindi binagong laro at nililikha ang eksaktong pakete ng compatibility shell nito.", "\uBCC0\uACBD\uB418\uC9C0 \uC54A\uC740 \uAC8C\uC784\uC744 \uBCF4\uC874\uD558\uACE0 \uC815\uD655\uD55C \uD328\uD0A4\uC9C0 \uD638\uD658\uC131 \uC258\uC744 \uC0DD\uC131 \uC911\uC785\uB2C8\uB2E4.", "\u672A\u6539\u5909\u306E\u30B2\u30FC\u30E0\u3092\u4FDD\u6301\u3057\u3001\u305D\u306E\u6B63\u78BA\u306A\u30D1\u30C3\u30B1\u30FC\u30B8\u4E92\u63DB\u30B7\u30A7\u30EB\u3092\u4F5C\u6210\u3057\u3066\u3044\u307E\u3059\u3002", "\u4FDD\u7559\u672A\u4FEE\u6539\u7684\u6E38\u620F\u5E76\u521B\u5EFA\u5176\u7CBE\u786E\u5305\u517C\u5BB9\u6027\u5916\u58F3\u3002", "Preservando el juego intacto y creando su shell de compatibilidad de paquete exacto.", "Gi\u1EEF nguy\u00EAn tr\u00F2 ch\u01A1i ch\u01B0a ch\u1EC9nh s\u1EEDa v\u00E0 t\u1EA1o l\u1EDBp t\u01B0\u01A1ng th\u00EDch g\u00F3i ch\u00EDnh x\u00E1c c\u1EE7a n\u00F3.", "Mempertahankan game yang tidak diubah dan membuat cangkang kompatibilitas paket tepatnya.", "Preservando o jogo intocado e criando seu shell de compatibilidade de pacote exato.", "الحفاظ على اللعبة التي لم تمسها وإنشاء غلاف متوافق تمامًا مع الحزمة."),
        "Preview" to arrayOf("Preview", "\uBBF8\uB9AC\uBCF4\uAE30", "\u30D7\u30EC\u30D3\u30E5\u30FC", "\u9884\u89C8", "Vista previa", "Xem tr\u01B0\u1EDBc", "Pratinjau", "Visualiza\u00E7\u00E3o", "معاينة"),
        "Preview of the launcher update window. No package will be downloaded." to arrayOf("Preview ng window ng update ng launcher. Walang package ang ida-download.", "\uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8 \uCC3D \uBBF8\uB9AC\uBCF4\uAE30. \uD328\uD0A4\uC9C0\uB294 \uB2E4\uC6B4\uB85C\uB4DC\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.", "\u30E9\u30F3\u30C1\u30E3\u30FC\u66F4\u65B0\u30A6\u30A3\u30F3\u30C9\u30A6\u306E\u30D7\u30EC\u30D3\u30E5\u30FC\u3002\u30D1\u30C3\u30B1\u30FC\u30B8\u306F\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3055\u308C\u307E\u305B\u3093\u3002", "\u542F\u52A8\u5668\u66F4\u65B0\u7A97\u53E3\u9884\u89C8\u3002\u4E0D\u4F1A\u4E0B\u8F7D\u4EFB\u4F55\u5305\u3002", "Vista previa de la ventana de actualizaci\u00F3n del lanzador. No se descargar\u00E1 ning\u00FAn paquete.", "Xem tr\u01B0\u1EDBc c\u1EEDa s\u1ED5 c\u1EADp nh\u1EADt tr\u00ECnh kh\u1EDFi ch\u1EA1y. Kh\u00F4ng g\u00F3i n\u00E0o s\u1EBD \u0111\u01B0\u1EE3c t\u1EA3i xu\u1ED1ng.", "Pratinjau jendela pembaruan peluncur. Tidak ada paket yang akan diunduh.", "Visualiza\u00E7\u00E3o da janela de atualiza\u00E7\u00E3o do lan\u00E7ador. Nenhum pacote ser\u00E1 baixado.", "معاينة نافذة تحديث المشغل. لن يتم تنزيل أي حزمة."),
        "Private add-on locked" to arrayOf("Pribadong add-on nakalock", "\uBE44\uACF5\uAC1C \uC560\uB4DC\uC628 \uC7A0\uAE40", "\u30D7\u30E9\u30A4\u30D9\u30FC\u30C8\u30A2\u30C9\u30AA\u30F3\u304C\u30ED\u30C3\u30AF\u3055\u308C\u3066\u3044\u307E\u3059", "\u79C1\u4EBA\u63D2\u4EF6\u5DF2\u9501\u5B9A", "Complemento privado bloqueado", "Ti\u1EC7n \u00EDch b\u1ED5 sung ri\u00EAng t\u01B0 b\u1ECB kh\u00F3a", "Add-on pribadi terkunci", "Complemento privado bloqueado", "الوظيفة الإضافية الخاصة مقفلة"),
        "Private approval check failed before a protected action; retaining local support" to arrayOf("Nabigong pumasa sa pribadong pagsusuri bago ang protektadong aksyon; pinananatili ang lokal na suporta", "\uBCF4\uD638\uB41C \uC791\uC5C5 \uC804\uC5D0 \uBE44\uACF5\uAC1C \uC2B9\uC778 \uD655\uC778 \uC2E4\uD328; \uB85C\uCEEC \uC9C0\uC6D0 \uC720\uC9C0", "\u4FDD\u8B77\u3055\u308C\u305F\u64CD\u4F5C\u306E\u524D\u306B\u30D7\u30E9\u30A4\u30D9\u30FC\u30C8\u627F\u8A8D\u30C1\u30A7\u30C3\u30AF\u304C\u5931\u6557\u3057\u307E\u3057\u305F; \u30ED\u30FC\u30AB\u30EB\u30B5\u30DD\u30FC\u30C8\u3092\u4FDD\u6301\u3057\u307E\u3059", "\u5728\u6267\u884C\u53D7\u4FDD\u62A4\u64CD\u4F5C\u4E4B\u524D\u79C1\u4EBA\u6279\u51C6\u68C0\u67E5\u5931\u8D25\uFF1B\u4FDD\u7559\u672C\u5730\u652F\u6301", "Fall\u00F3 la verificaci\u00F3n de aprobaci\u00F3n privada antes de una acci\u00F3n protegida; manteniendo el soporte local", "Ki\u1EC3m tra ph\u00EA duy\u1EC7t ri\u00EAng t\u01B0 kh\u00F4ng th\u00E0nh c\u00F4ng tr\u01B0\u1EDBc h\u00E0nh \u0111\u1ED9ng \u0111\u01B0\u1EE3c b\u1EA3o v\u1EC7; gi\u1EEF h\u1ED7 tr\u1EE3 c\u1EE5c b\u1ED9", "Pemeriksaan persetujuan pribadi gagal sebelum tindakan terlindungi; mempertahankan dukungan lokal", "Falha na verifica\u00E7\u00E3o de aprova\u00E7\u00E3o privada antes de uma a\u00E7\u00E3o protegida; mantendo suporte local", "فشل التحقق من الموافقة الخاصة قبل إجراء محمي؛ الحفاظ على الدعم المحلي"),
        "Private module approval could not be refreshed; retaining cached support." to arrayOf("Hindi ma-refresh ang aprubal ng pribadong module; pinananatili ang naka-cache na suporta.", "\uBE44\uACF5\uAC1C \uBAA8\uB4C8 \uC2B9\uC778\uC744 \uC0C8\uB85C\uACE0\uCE68\uD560 \uC218 \uC5C6\uC74C; \uCE90\uC2DC\uB41C \uC9C0\uC6D0 \uC720\uC9C0", "\u30D7\u30E9\u30A4\u30D9\u30FC\u30C8\u30E2\u30B8\u30E5\u30FC\u30EB\u627F\u8A8D\u3092\u66F4\u65B0\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F; \u30AD\u30E3\u30C3\u30B7\u30E5\u3055\u308C\u305F\u30B5\u30DD\u30FC\u30C8\u3092\u4FDD\u6301\u3057\u307E\u3059\u3002", "\u65E0\u6CD5\u5237\u65B0\u79C1\u4EBA\u6A21\u5757\u6279\u51C6\uFF1B\u4FDD\u7559\u7F13\u5B58\u7684\u652F\u6301\u3002", "No se pudo actualizar la aprobaci\u00F3n del m\u00F3dulo privado; manteniendo el soporte almacenado en cach\u00E9.", "Kh\u00F4ng th\u1EC3 l\u00E0m m\u1EDBi ph\u00EA duy\u1EC7t m\u00F4-\u0111un ri\u00EAng t\u01B0; gi\u1EEF h\u1ED7 tr\u1EE3 l\u01B0u trong b\u1ED9 nh\u1EDB \u0111\u1EC7m.", "Persetujuan modul pribadi tidak dapat diperbarui; mempertahankan dukungan yang disimpan.", "Aprova\u00E7\u00E3o do m\u00F3dulo privado n\u00E3o p\u00F4de ser atualizada; mantendo suporte em cache.", "لا يمكن تحديث الموافقة على الوحدة الخاصة؛ الاحتفاظ بالدعم المخزن مؤقتًا."),
        "Proving package integrity and signed identity." to arrayOf("Pinapatunayan ang integridad ng package at pirmahang pagkakakilanlan.", "\uD328\uD0A4\uC9C0 \uBB34\uACB0\uC131\uACFC \uC11C\uBA85\uB41C \uC2E0\uC6D0 \uD655\uC778 \uC911", "\u30D1\u30C3\u30B1\u30FC\u30B8\u306E\u6574\u5408\u6027\u3068\u7F72\u540D\u3055\u308C\u305F\u8EAB\u5143\u3092\u691C\u8A3C\u3057\u3066\u3044\u307E\u3059\u3002", "\u9A8C\u8BC1\u5305\u5B8C\u6574\u6027\u548C\u7B7E\u540D\u8EAB\u4EFD\u3002", "Verificando la integridad del paquete y la identidad firmada.", "\u0110ang ch\u1EE9ng minh t\u00EDnh to\u00E0n v\u1EB9n c\u1EE7a g\u00F3i v\u00E0 danh t\u00EDnh \u0111\u00E3 k\u00FD.", "Memeriksa integritas paket dan identitas yang ditandatangani.", "Verificando a integridade do pacote e identidade assinada.", "إثبات سلامة الحزمة والهوية الموقعة."),
        "Ready after launcher access is restored" to arrayOf("Handa pagkatapos maibalik ang access sa launcher", "\uB7F0\uCC98 \uC811\uADFC\uC774 \uBCF5\uC6D0\uB41C \uD6C4 \uC900\uBE44 \uC644\uB8CC", "\u30E9\u30F3\u30C1\u30E3\u30FC\u30A2\u30AF\u30BB\u30B9\u304C\u5FA9\u5143\u3055\u308C\u305F\u5F8C\u3001\u6E96\u5099\u5B8C\u4E86", "\u542F\u52A8\u5668\u8BBF\u95EE\u6062\u590D\u540E\u5DF2\u5C31\u7EEA", "Listo despu\u00E9s de que se restaur\u00F3 el acceso del lanzador", "S\u1EB5n s\u00E0ng sau khi quy\u1EC1n truy c\u1EADp tr\u00ECnh kh\u1EDFi ch\u1EA1y \u0111\u01B0\u1EE3c kh\u00F4i ph\u1EE5c", "Siap setelah akses peluncur dipulihkan", "Pronto ap\u00F3s o acesso ao lan\u00E7ador ser restaurado", "جاهز بعد استعادة الوصول إلى المشغل"),
        "Recovered a verified package setup after launcher restart" to arrayOf("Na-recover ang na-verify na setup ng package pagkatapos ng restart ng launcher", "\uB7F0\uCC98 \uC7AC\uC2DC\uC791 \uD6C4 \uAC80\uC99D\uB41C \uD328\uD0A4\uC9C0 \uC124\uC815 \uBCF5\uAD6C", "\u30E9\u30F3\u30C1\u30E3\u30FC\u518D\u8D77\u52D5\u5F8C\u3001\u691C\u8A3C\u6E08\u307F\u30D1\u30C3\u30B1\u30FC\u30B8\u8A2D\u5B9A\u3092\u5FA9\u5143\u3057\u307E\u3057\u305F", "\u542F\u52A8\u5668\u91CD\u542F\u540E\u6062\u590D\u4E86\u5DF2\u9A8C\u8BC1\u7684\u5305\u8BBE\u7F6E", "Se recuper\u00F3 una configuraci\u00F3n de paquete verificada despu\u00E9s del reinicio del lanzador", "Kh\u00F4i ph\u1EE5c thi\u1EBFt l\u1EADp g\u00F3i \u0111\u00E3 x\u00E1c minh sau khi kh\u1EDFi ch\u1EA1y l\u1EA1i tr\u00ECnh kh\u1EDFi ch\u1EA1y", "Mengembalikan pengaturan paket yang diverifikasi setelah peluncur dimulai ulang", "Configura\u00E7\u00E3o de pacote verificada recuperada ap\u00F3s rein\u00EDcio do lan\u00E7ador", "تم استرداد إعداد الحزمة التي تم التحقق منها بعد إعادة تشغيل المشغل"),
        "Refusing to open an untrusted web address" to arrayOf("Tumangging buksan ang hindi mapagkakatiwalaang web address", "\uC2E0\uB8B0\uD560 \uC218 \uC5C6\uB294 \uC6F9 \uC8FC\uC18C \uC5F4\uAE30 \uAC70\uBD80", "\u4FE1\u983C\u3055\u308C\u3066\u3044\u306A\u3044\u30A6\u30A7\u30D6\u30A2\u30C9\u30EC\u30B9\u306E\u958B\u5C01\u3092\u62D2\u5426\u3057\u307E\u3057\u305F", "\u62D2\u7EDD\u6253\u5F00\u4E0D\u53D7\u4FE1\u4EFB\u7684\u7F51\u9875\u5730\u5740", "Rechazando abrir una direcci\u00F3n web no confiable", "T\u1EEB ch\u1ED1i m\u1EDF \u0111\u1ECBa ch\u1EC9 web kh\u00F4ng \u0111\u00E1ng tin c\u1EADy", "Menolak membuka alamat web yang tidak tepercaya", "Recusando abrir um endere\u00E7o web n\u00E3o confi\u00E1vel", "رفض فتح عنوان ويب غير موثوق به"),
        "Release verification completed in browser" to arrayOf("Nakumpleto ang beripikasyon ng release sa browser", "\uBE0C\uB77C\uC6B0\uC800\uC5D0\uC11C \uB9B4\uB9AC\uC2A4 \uAC80\uC99D \uC644\uB8CC", "\u30D6\u30E9\u30A6\u30B6\u3067\u30EA\u30EA\u30FC\u30B9\u78BA\u8A8D\u304C\u5B8C\u4E86\u3057\u307E\u3057\u305F", "\u6D4F\u89C8\u5668\u4E2D\u5DF2\u5B8C\u6210\u53D1\u5E03\u9A8C\u8BC1", "Verificaci\u00F3n de lanzamiento completada en el navegador", "X\u00E1c minh ph\u00E1t h\u00E0nh \u0111\u00E3 ho\u00E0n t\u1EA5t trong tr\u00ECnh duy\u1EC7t", "Verifikasi rilis selesai di browser", "Verifica\u00E7\u00E3o de lan\u00E7amento conclu\u00EDda no navegador", "اكتمل التحقق من الإصدار في المتصفح"),
        "Remove selected ({0})" to arrayOf("Alisin ang napili ({0})", "\uC120\uD0DD \uD56D\uBAA9 \uC81C\uAC70 ({0})", "\u9078\u629E\u3057\u305F\u3082\u306E\u3092\u524A\u9664 ({0})", "\u79FB\u9664\u6240\u9009\u9879\uFF08{0}\uFF09", "Eliminar seleccionado ({0})", "X\u00F3a c\u00E1c m\u1EE5c \u0111\u00E3 ch\u1ECDn ({0})", "Hapus yang dipilih ({0})", "Remover selecionado ({0})", "إزالة المحدد ({0})"),
        "Remove the current installation" to arrayOf("Alisin ang kasalukuyang installation", "\uD604\uC7AC \uC124\uCE58 \uC81C\uAC70", "\u73FE\u5728\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u524A\u9664", "\u79FB\u9664\u5F53\u524D\u5B89\u88C5", "Eliminar la instalaci\u00F3n actual", "X\u00F3a c\u00E0i \u0111\u1EB7t hi\u1EC7n t\u1EA1i", "Hapus instalasi saat ini", "Remover a instala\u00E7\u00E3o atual", "قم بإزالة التثبيت الحالي"),
